"Все скрипачи — музыканты. Как нарисовать круги «Скрипачи» и «Музыканты»?": "Ҳамаи скрипканавозон — навозанда. Давраҳои «Скрипканавозон» ва «Навозандагон»-ро чӣ тавр кашидан лозим?",
"Участок имеет форму квадрата со стороной 40 м. Сколько ар в его площади?": "Қитъа шакли квадрат бо тарафи 40 м дорад. Дар масоҳаташ чанд ар ҳаст?",
