"Число, которое делят, называют делимым. Делитель — число, на которое делят.": "Ададеро, ки тақсим мекунанд, тақсимшаванда меноманд. Тақсимкунанда — ададест, ки ба он тақсим мекунанд.",
"Любители плова и любители бауырсаков в одном классе (есть и такие, и такие)": "Дӯстдорони палав ва дӯстдорони бауырсак дар як синф (ҳам чунин, ҳам чунин ҳастанд)",
"200 оканчивается на 2 нуля: 200 : 100 = 2. В остальных числах нулей меньше.": "200 ба 2 сифр анҷом меёбад: 200 : 100 = 2. Дар ададҳои дигар сифрҳо камтаранд.",
