"Общие элементы при сложении посчитаны дважды, поэтому один раз их вычитаем.": "Унсурҳои умумӣ ҳангоми ҷамъ ду маротиба шумурда шудаанд, барои ҳамин онҳоро як маротиба тарҳ мекунем.",
