"Если справа цифра от 5 до 9, разряд увеличиваем на 1. Пример: 3 764 ≈ 3 800.": "Агар дар рост рақам аз 5 то 9 бошад, разрядро 1 зиёд мекунем. Мисол: 3 764 ≈ 3 800.",
