"Объём измеряют в кубических единицах (см³, дм³, м³). Квадратные — для площади.": "Ҳаҷмро бо воҳидҳои мукааб (см³, дм³, м³) чен мекунанд. Мураббаъҳо — барои масоҳат.",
"Круги Эйлера: «делятся на 2» и «делятся на 5». Где нужно записать число 7 845?": "Давраҳои Эйлер: «ба 2 тақсим мешаванд» ва «ба 5 тақсим мешаванд». Адади 7 845-ро дар куҷо навиштан лозим?",
"Круги Эйлера: «делятся на 2» и «делятся на 5». Где нужно записать число 7 845?": "Давраҳои Эйлер: «ба 2 тақсим мешаванд» ва «ба 5 тақсим мешаванд». Адади 7 845-ро дар куҷо навиштан лозим?",
"V = 8 · 4 · 4 = 128 дм³. 1 дм³ вмещает 1 л воды, значит в аквариум входит 128 л": "V = 8 · 4 · 4 = 128 дм³. 1 дм³ 1 л об мегирад, пас ба аквариум 128 л ҷо мешавад",
"Пересечение двух множеств всегда содержит больше элементов, чем их объединение.": "Буриши ду маҷмӯа ҳамеша аз иттиҳодашон бештар унсур дорад.",
