"S = 30 · 30 + 30 · 40 = 900 + 1 200 = 2 100 дм². 2 100 : 100 = 21. Нужно 21 м².": "S = 30 · 30 + 30 · 40 = 900 + 1 200 = 2 100 дм². 2 100 : 100 = 21. 21 м² лозим аст.",
"Велосипедист едет со скоростью 12 км/ч. Сколько километров он проедет за 3 часа?": "Велосипедрон бо суръати 12 км/соат меравад. Дар 3 соат чанд километр мегузарад?",
"Куб с ребром 8 см распилили на кубики с ребром 1 см. Сколько кубиков получилось?": "Кубро бо қабурғаи 8 см ба кубикҳои бо қабурғаи 1 см арра карданд. Чандто кубик баромад?",
"Уменьшаемое − вычитаемое = разность. Значит, уменьшаемое = разность + вычитаемое.": "Камшаванда − тарҳшаванда = фарқ. Пас, камшаванда = фарқ + тарҳшаванда.",
"Проверим умножением: 8 281 · 7 = 57 967. В остальных равенствах частное неверное.": "Бо зарб месанҷем: 8 281 · 7 = 57 967. Дар баробариҳои дигар ҳосили тақсим нодуруст аст.",
"Проверим умножением: 8 281 · 7 = 57 967. В остальных равенствах частное неверное.": "Бо зарб месанҷем: 8 281 · 7 = 57 967. Дар баробариҳои дигар ҳосили тақсим нодуруст аст.",
