"Сочетательное свойство пересечения: скобки можно переставить, знаки остаются те же.": "Хосияти гурӯҳбандии буриш: қавсҳоро ҷо ба ҷо кардан мумкин, аломатҳо ҳамон мемонанд.",
"Отделяем справа одну цифру: 5 — остаток, 89 — частное. Проверка: 89 · 10 + 5 = 895.": "Аз рост як рақамро ҷудо мекунем: 5 — бақия, 89 — ҳосили тақсим. Санҷиш: 89 · 10 + 5 = 895.",
