"Дано множество A = {И, К, С, Р, Л, О}. Какое из множеств — подмножество множества A?": "Маҷмӯаи A = {И, К, С, Р, Л, О} дода шудааст. Кадом маҷмӯа зермаҷмӯаи маҷмӯаи A аст?",
"Складываем единицы с единицами, потом десятки с десятками и так далее — справа налево": "Ягонаҳоро бо ягонаҳо, баъд даҳҳоро бо даҳҳо ҷамъ мекунем ва ҳамин тавр — аз рост ба чап",
