"В классе 20 любят чай, 15 любят какао, 7 — и то и другое. Сколько любят чай или какао?": "Дар синф 20 нафар чой, 15 нафар какао дӯст медоранд, 7 нафар — ҳам ин ва ҳам он. Чанд нафар чой ё какао дӯст медоранд?",
"На 10 делятся числа, которые оканчиваются на 0. Подходит цифра 0: 13 870 : 10 = 1 387.": "Ба 10 ададҳое тақсим мешаванд, ки бо 0 анҷом меёбанд. Рақами 0 мувофиқ аст: 13 870 : 10 = 1 387.",
"На 10 делятся числа, которые оканчиваются на 0. Подходит цифра 0: 13 870 : 10 = 1 387.": "Ба 10 ададҳое тақсим мешаванд, ки бо 0 анҷом меёбанд. Рақами 0 мувофиқ аст: 13 870 : 10 = 1 387.",
