"Проверяем так: частное · делитель + остаток = делимое. Пример: 807 · 100 + 86 = 80 786.": "Ин тавр месанҷем: ҳосили тақсим · тақсимкунанда + бақия = тақсимшаванда. Мисол: 807 · 100 + 86 = 80 786.",
"45 678 · 4 = 182 712. Умножаем по разрядам, начиная с единиц, и не забываем про перенос.": "45 678 · 4 = 182 712. Аз рӯи разрядҳо, аз ягонаҳо сар карда зарб мекунем ва гузаришро фаромӯш намекунем.",
"45 678 · 4 = 182 712. Умножаем по разрядам, начиная с единиц, и не забываем про перенос.": "45 678 · 4 = 182 712. Аз рӯи разрядҳо, аз ягонаҳо сар карда зарб мекунем ва гузаришро фаромӯш намекунем.",
"A = { 1; 4; 8; 9; 11 }, B = { 4; 8; 10; 11; 12 }. Сколько элементов в объединении A ∪ B?": "A = { 1; 4; 8; 9; 11 }, B = { 4; 8; 10; 11; 12 }. Дар иттиҳоди A ∪ B чандто унсур аст?",
