"1 л воды занимает объём 1 дм³. Пример: в аквариум 4 дм × 5 дм × 3 дм вмещается 60 л воды.": "1 л об ҳаҷми 1 дм³-ро ишғол мекунад. Мисол: ба аквариуми 4 дм × 5 дм × 3 дм 60 л об ҷо мешавад.",
"Дина в Нью-Йорке купила сувенир за 53 $ и открытки за 4 $. Сколько долларов она заплатила?": "Дина дар Ню-Йорк сувенир ба 53 $ ва откритка ба 4 $ харид. Чанд доллар пардохт кард?",
"В одном слое 3 · 4 = 12 кубиков. Всего 36 кубиков, поэтому слоёв 36 : 12 = 3. Высота 3 см.": "Дар як қабат 3 · 4 = 12 кубик. Ҳамагӣ 36 кубик, пас қабатҳо 36 : 12 = 3. Баландӣ 3 см.",
"Чтобы найти число кубиков в коробке, считают кубики в одном слое и умножают на число слоёв.": "Барои ёфтани шумораи кубикҳо дар қуттӣ, кубикҳои як қабатро мешуморанд ва ба шумораи қабатҳо зарб мекунанд.",
"Привет! Это Барсик. Сегодня учимся складывать большие числа столбиком. Нажимай на карточки.": "Салом! Ман Барсик. Имрӯз ҷамъ кардани ададҳои калонро бо сутун меомӯзем. Ба кортҳо пахш кун.",
"Площадь прямоугольника: 10 · 9 = 90 м². Площадь выреза: 5 · 5 = 25 м². S = 90 − 25 = 65 м².": "Масоҳати росткунҷа: 10 · 9 = 90 м². Масоҳати бурида: 5 · 5 = 25 м². S = 90 − 25 = 65 м².",
"Сколько кубиков с ребром 1 см поместится в коробку длиной 8 см, шириной 8 см и высотой 8 см?": "Дар қуттии дарозиаш 8 см, бараш 8 см ва баландиаш 8 см чандто кубики бо қабурғаи 1 см ҷо мешавад?",
"В группе 18 бегунов и 12 прыгунов, 5 занимаются обоими видами. Сколько спортсменов в группе?": "Дар гурӯҳ 18 даванда ва 12 ҷаҳанда ҳаст, 5 нафар ба ҳарду навъ машғуланд. Дар гурӯҳ чандто варзишгар ҳаст?",
"Первая часть: 60 · 3 = 180 км. Вторая часть: 50 · 2 = 100 км. Весь путь: 180 + 100 = 280 км.": "Қисми якум: 60 · 3 = 180 км. Қисми дуюм: 50 · 2 = 100 км. Тамоми роҳ: 180 + 100 = 280 км.",
"В магазине предлагают: 840 тг за 3 кг мандаринов или 1 800 тг за 5 кг. Где мандарины дешевле?": "Дар мағоза пешниҳод мекунанд: 840 тг барои 3 кг норинҷ ё 1 800 тг барои 5 кг. Норинҷ дар куҷо арзонтар аст?",
"В магазине предлагают: 840 тг за 3 кг мандаринов или 1 800 тг за 5 кг. Где мандарины дешевле?": "Дар мағоза пешниҳод мекунанд: 840 тг барои 3 кг норинҷ ё 1 800 тг барои 5 кг. Норинҷ дар куҷо арзонтар аст?",
"7 · 621 = 4347. 4 350 − 4347 = 3. Остаток 3 меньше делителя 7. Проверка: 7 · 621 + 3 = 4 350.": "7 · 621 = 4347. 4 350 − 4347 = 3. Бақияи 3 аз тақсимкунандаи 7 хурд аст. Санҷиш: 7 · 621 + 3 = 4 350.",
"7 · 621 = 4347. 4 350 − 4347 = 3. Остаток 3 меньше делителя 7. Проверка: 7 · 621 + 3 = 4 350.": "7 · 621 = 4347. 4 350 − 4347 = 3. Бақияи 3 аз тақсимкунандаи 7 хурд аст. Санҷиш: 7 · 621 + 3 = 4 350.",
"Читаем по классам: «двадцать шесть миллионов», «восемьсот девяносто тысяч», «девятьсот девять».": "Аз рӯи синфҳо мехонем: «бисту шаш миллион», «ҳаштсаду навад ҳазор», «нӯҳсаду нӯҳ».",
"Тех, кто занимается и тем и другим, при сложении посчитали дважды. 16 + 10 − 4 = 22. Ответ: 22.": "Онҳоеро, ки ҳам ба ин ва ҳам ба он машғуланд, ҳангоми ҷамъ ду маротиба шуморидаанд. 16 + 10 − 4 = 22. Ҷавоб: 22.",
"Площадь всего прямоугольника: 13 · 10 = 130 м². Площадь выреза: 4 · 2 = 8 м². 130 − 8 = 122 м².": "Масоҳати тамоми росткунҷа: 13 · 10 = 130 м². Масоҳати бурида: 4 · 2 = 8 м². 130 − 8 = 122 м².",
"Переводить единицы площади, объёма, времени и массы и выполнять действия с составными величинами": "Табдили воҳидҳои масоҳат, ҳаҷм, вақт ва масса ва иҷрои амалҳо бо миқдорҳои таркибӣ",
"На 2 делятся числа, которые оканчиваются на 0, 2, 4, 6, 8. Подходит цифра 2: 95 362 : 2 = 47 681.": "Ба 2 ададҳое тақсим мешаванд, ки бо 0, 2, 4, 6, 8 анҷом меёбанд. Рақами 2 мувофиқ аст: 95 362 : 2 = 47 681.",
"На 2 делятся числа, которые оканчиваются на 0, 2, 4, 6, 8. Подходит цифра 2: 95 362 : 2 = 47 681.": "Ба 2 ададҳое тақсим мешаванд, ки бо 0, 2, 4, 6, 8 анҷом меёбанд. Рақами 2 мувофиқ аст: 95 362 : 2 = 47 681.",
