"Спринтер бежит со скоростью 7 м/с. За сколько секунд он преодолеет 84 м?": "Спринтер бо суръати 7 м/с медавад. Дар чанд сония 84 м-ро тай мекунад?",
"Так считать нельзя. Нужно занять 1 единицу у соседнего старшего разряда.": "Чунин ҳисоб кардан мумкин нест. Бояд 1 воҳидро аз ҳонаи калони ҳамсоя қарз гирифт.",
"Результат деления называют частным, например 56 : 8 = 7, где 7 — частное.": "Натиҷаи тақсимро ҳосили тақсим меноманд, масалан 56 : 8 = 7, ки 7 — ҳосили тақсим аст.",
