"При сложении числа элементов двух множеств общие элементы считают дважды.": "Ҳангоми ҷамъи шумораи унсурҳои ду маҷмӯъ унсурҳои умумиро ду бор меҳисобанд.",
"Оканчивается на 5 — делится на 5. Но на 2 и на 10 такие числа не делятся.": "Ба 5 анҷом меёбад — ба 5 тақсим мешавад. Аммо ба 2 ва ба 10 чунин ададҳо тақсим намешаванд.",
