"До школы 900 м. Арман проходит 60 м за минуту. За сколько минут он дойдёт?": "То мактаб 900 м аст. Арман дар як дақиқа 60 м тай мекунад. Дар чанд дақиқа мерасад?",
"В делителе 3 нуля, значит, отделяем три цифры. Отделённые цифры — остаток.": "Дар тақсимкунанда 3 сифр аст, пас се рақамро ҷудо мекунем. Рақамҳои ҷудошуда — бақия.",
