"Разность равна 33 654, вычитаемое — 32 738, тогда уменьшаемое равно 66 392.": "Тафовут ба 33 654 баробар аст, тарҳшаванда — 32 738, пас камшаванда ба 66 392 баробар аст.",
"Самолёт летит со скоростью 800 км/ч. Сколько километров он пролетит за 3 ч?": "Ҳавопаймо бо суръати 800 км/соат парвоз мекунад. Дар 3 соат чанд километр парвоз мекунад?",
"Общие элементы — это пересечение. Объединение — все элементы из A или из B.": "Унсурҳои умумӣ — ин буриш аст. Иттиҳод — ҳамаи унсурҳо аз A ё аз B.",
"Повторить задачи на движение, действия с множествами, объём и площадь фигур": "Такрор кардани масъалаҳо оид ба ҳаракат, амалҳо бо маҷмӯъҳо, ҳаҷм ва масоҳати шаклҳо",
"Круги Эйлера: «делятся на 2» и «делятся на 5». Где нужно записать число 825?": "Давраҳои Эйлер: «ба 2 тақсим мешаванд» ва «ба 5 тақсим мешаванд». Адади 825-ро дар кадом ҷо навиштан лозим?",
"Мелких единиц получается больше, поэтому умножаем. Например, 4 г = 4 000 мг.": "Воҳидҳои хурд зиёдтар мешаванд, бинобар ин зарб мекунем. Масалан, 4 г = 4 000 мг.",
"Чтобы найти неизвестное слагаемое, надо из суммы вычесть известное слагаемое.": "Барои ёфтани ҷамъшавандаи номаълум бояд аз ҷамъ ҷамъшавандаи маълумро тарҳ кард.",
