"Из прямоугольника 15 м × 8 м вырезали прямоугольник 2 м × 4 м. Осталось 112 м².": "Аз росткунҷаи 15 м × 8 м росткунҷаи 2 м × 4 м бурида гирифтанд. 112 м² монд.",
