"Сумма равна 119 959, одно слагаемое — 96 376, тогда второе слагаемое равно 23 583.": "Ҷамъ ба 119 959 баробар аст, як ҷамъшаванда — 96 376, пас ҷамъшавандаи дуюм ба 23 583 баробар аст.",
"Сумма равна 124 598, одно слагаемое — 93 157, тогда второе слагаемое равно 32 441.": "Ҷамъ ба 124 598 баробар аст, як ҷамъшаванда — 93 157, пас ҷамъшавандаи дуюм ба 32 441 баробар аст.",
