"До города 360 км. Автобус едет 60 км/ч. Сколько часов в пути?": "То шаҳр 360 км. Автобус бо суръати 60 км/соат меравад. Чанд соат дар роҳ аст?",
"Нужно число больше 53 410, которое оканчивается на 0: 53 420.": "Ададе лозим аст, ки аз 53 410 калон бошад ва ба 0 анҷом ёбад: 53 420.",
"Нужно число больше 53 410, которое оканчивается на 0: 53 420.": "Ададе лозим аст, ки аз 53 410 калон бошад ва ба 0 анҷом ёбад: 53 420.",
"Если вычесть 0, число не меняется. Например, 5 000 − 0 = 5 000": "Агар 0 тарҳ кунем, адад тағйир намеёбад. Масалан, 5 000 − 0 = 5 000",
"До озера 24 км. Турист идёт по 4 км в час. Сколько часов идти?": "То кӯл 24 км. Сайёҳ дар як соат 4 км мегузарад. Чанд соат роҳ рафтан лозим аст?",
"Автобус ехал 3 ч со скоростью 60 километров в час. Какой путь?": "Автобус 3 соат бо суръати 60 километр дар як соат рафт. Роҳ чанд аст?",
"Как найти время движения, если известны расстояние и скорость?": "Вақти ҳаракатро агар масофа ва суръат маълум бошанд, чӣ тавр меёбанд?",
"Тетрадь маленькая, её площадь измеряют в квадратных сантиметрах": "Дафтар хурд аст, масоҳати онро бо сантиметри мураббаъ ченак мекунанд",
"До аула 90 км. Машина едет по 45 км в час. Сколько часов ехать?": "То аул 90 км. Мошин дар як соат 45 км меравад. Чанд соат рафтан лозим аст?",
