"половина: 30 минут после целого часа. 4 ч 30 мин — это половина пятого": "ним: 30 дақиқа баъд аз соати пурра. 4 соат 30 дақ — ин чоруним",
"Школьник проходит 80 м за минуту. Сколько метров он пройдёт за 10 мин?": "Хонанда дар як дақиқа 80 м мегузарад. Дар 10 дақ чанд метр мегузарад?",
