"Сначала деление: 34 236 : 9 = 3 804. Потом вычитание: 3 804 − 70 = 3 734.": "Аввал тақсим: 34 236 : 9 = 3 804. Баъд тарҳ: 3 804 − 70 = 3 734.",
"Сначала деление: 34 236 : 9 = 3 804. Потом вычитание: 3 804 − 70 = 3 734.": "Аввал тақсим: 34 236 : 9 = 3 804. Баъд тарҳ: 3 804 − 70 = 3 734.",
"В 1 м³ содержится 1 000 дм³. 2 000 : 1 000 = 2. Значит, 2 000 дм³ = 2 м³.": "Дар 1 м³ 1 000 дм³ ҷой дорад. 2 000 : 1 000 = 2. Пас 2 000 дм³ = 2 м³.",
"В 1 м³ содержится 1 000 дм³. 2 000 : 1 000 = 2. Значит, 2 000 дм³ = 2 м³.": "Дар 1 м³ 1 000 дм³ ҷой дорад. 2 000 : 1 000 = 2. Пас 2 000 дм³ = 2 м³.",
"При делении числа на 100 получили частное 172 и остаток 6. Найди делимое.": "Ҳангоми тақсими адад ба 100 тақсимоти 172 ва бақияи 6 ҳосил шуд. Тақсимшавандаро ёб.",
"ответ 6: 1/4 сут. = 6 ч; 1/10 ч = 6 мин; 1/2 года = 6 мес.; 1/10 мин = 6 с": "ҷавоб 6: 1/4 шабонарӯз = 6 соат; 1/10 соат = 6 дақ; 1/2 сол = 6 моҳ; 1/10 дақ = 6 сон",
"Как найти скорость удаления, если тела движутся в противоположные стороны?": "Суръати дур шуданро чӣ тавр меёбанд, агар ҷисмҳо ба самтҳои муқобил ҳаракат кунанд?",
"Расстояние между ними сокращается, они выехали из разных мест друг к другу": "Масофа дар байни онҳо кам мешавад, онҳо аз ҷойҳои гуногун ба пешвози якдигар баромаданд",
"8 · 7 = 56. Единицы пишем под чертой, десятки переносим в следующий разряд.": "8 · 7 = 56. Яклиҳоро зери хат менависем, даҳгониро ба разряди оянда мегузаронем.",
"Они удаляются друг от друга обоими движениями, поэтому скорости складываем.": "Онҳо бо ҳар ду ҳаракат аз якдигар дур мешаванд, барои ҳамин суръатҳоро ҷамъ мекунем.",
"Это единица объёма. Площадь измеряют в квадратных единицах, например в см².": "Ин воҳиди ҳаҷм аст. Масоҳатро бо воҳидҳои мураббаъ ченак мекунанд, масалан бо см².",
"Раздели число на классы по три цифры справа налево. Третий класс — миллионы.": "Ададро аз рост ба чап ба синфҳои сегона ҷудо кун. Синфи сеюм — миллионҳо.",
"Множества «Овощи» и «Фрукты» не имеют общих элементов. Как нарисовать круги?": "Маҷмӯаҳои «Сабзавот» ва «Мева» унсури умумӣ надоранд. Доираҳоро чӣ тавр мекашем?",
"На складе 90 415 кг муки в мешках по 10 кг. Сколько полных мешков получится?": "Дар анбор 90 415 кг орд дар халтаҳои 10 килограммӣ. Чанд халтаи пур ҳосил мешавад?",
"На складе 90 415 кг муки в мешках по 10 кг. Сколько полных мешков получится?": "Дар анбор 90 415 кг орд дар халтаҳои 10 килограммӣ. Чанд халтаи пур ҳосил мешавад?",
"Сравни цифры по разрядам справа налево. Если сверху цифра меньше, нужен заём.": "Рақамҳоро аз рӯи разрядҳо аз рост ба чап муқоиса кун. Агар рақами боло хурдтар бошад, қарз лозим аст.",
"Скорость измеряют в единицах расстояния за единицу времени: км/ч, м/мин, м/с.": "Суръатро бо воҳиди масофа дар як воҳиди вақт ченак мекунанд: км/соат, м/дақ, м/сон.",
"Объём коробки 36 см³. Длина коробки 3 см, ширина 4 см. Какова высота коробки?": "Ҳаҷми қутти 36 см³. Дарозии қутти 3 см, бари он 4 см. Баландии қутти чанд аст?",
"У числа 100 234 шесть цифр, а у остальных по пять. Больше цифр — больше число.": "Адади 100 234 шаш рақам дорад, дигарҳо панҷтогӣ. Рақам зиёд — адад калон.",
"Все элементы A есть в B, а B больше: A — подмножество B. Это записывают A ⊂ B.": "Ҳамаи унсурҳои A дар B ҳастанд, B калонтар аст: A — зермаҷмӯаи B. Инро чунин менависанд: A ⊂ B.",
"1 кг = 1 000 г, а 1 г = 1 000 мг. Значит, 1 кг = 1 000 · 1 000 = 1 000 000 мг.": "1 кг = 1 000 г, 1 г = 1 000 мг. Пас 1 кг = 1 000 · 1 000 = 1 000 000 мг.",
