"Число 1 595 можно записать в пересечение кругов «делятся на 2» и «делятся на 5».": "Адади 1 595-ро дар буриши доираҳои «ба 2 тақсим мешавад» ва «ба 5 тақсим мешавад» навиштан мумкин аст.",
